import sys

def solve():
    import sys
    input = sys.stdin.read().split()

    index = 0
    t = int(input[index])
    index += 1

    results = []

    for _ in range(t):
        n = int(input[index])
        k = int(input[index + 1])
        s = input[index + 2]
        index += 3

        if k == 1:
            results.append(s.count('B'))
            continue

        count_operations = 0
        black_count = 0

        for i in range(k):
            if s[i] == 'B':
                black_count += 1

        if black_count > 0:
            count_operations += 1

        for i in range(k, n):
            if s[i - k] == 'B':
                black_count -= 1
            if s[i] == 'B':
                black_count += 1
            if black_count > 0:
                count_operations += 1

        results.append(count_operations)

    for result in results:
        print(result)

if __name__ == '__main__':
    solve()

class Solution:
    def maxStrength(self, nums: List[int]) -> int:
        # Sort the numbers to handle negative numbers and zeroes easily
        nums.sort()

        # Initialize the result to 1 (multiplicative identity)
        result = 1
        has_positive = False

        # Iterate through the sorted numbers
        for num in nums:
            if num > 0:
                # Include all positive numbers
                result *= num
                has_positive = True
            elif num < 0:
                # Include pairs of negative numbers
                if len(nums) % 2 == 1 and nums[-1] == num:
                    # If there's an odd number of negative numbers and we're at the last one, skip it
                    continue
                result *= num

        # If there are no positive numbers and an odd number of negative numbers, return the largest negative number
        if not has_positive and len(nums) % 2 == 1:
            return nums[-1]

        return result
